200,1,'info','127.0.0.1','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/154.0.0.0 Safari/537.36 Edg/154.0.0.0',3,'','backend',NULL,'2026-10-01 11:00:18','{accept=application/json, text/plain, */*, accept-language=zh-CN,zh;q=0.9,en-US;q=0.8,en;q=0.7,en-GB;q=0.6, referer=http://127.0.0.1/admin/project-config, user-agent=Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/154.0.0.0 Safari/537.36 Edg/154.0.0.0, x-forwarded-for=127.0.0.1}',NULL,'{\"code\":200,\"message\":\"ok\",\"data\":{\"java\":{\"label\":\"Java 后端配置（application-dev.yml）\",\"tip\":\"端口、数据库、Redis、JWT、OSS、上传大小等后端运行参数。修改后需重启后端服务生效。\",\"path\":\"C:/Users/25750/Desktop/usmind/code/backend/src/main/resources/application-dev.yml\",\"content\":\"spring:\\r\\n  datasource:\\r\\n    driver-class-name: com.mysql.cj.jdbc.Driver\\r\\n    url: jdbc:mysql://127.0.0.1:3306/usmind_db?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai&useSSL=false&allowPublicKeyRetrieval=true\\r\\n    username: root\\r\\n    password: root\\r\\n  data:\\r\\n    redis:\\r\\n      host: 127.0.0.1\\r\\n      port: 6379\\r\\n      password:\\r\\n      database: 0\\r\\n\",\"exists\":true},\"nginx\":{\"label\":\"Nginx 配置（nginx.conf）\",\"tip\":\"监听端口、站点入口、API 反向代理、上传文件缓存等。修改后需执行 nginx -s reload 生效。\",\"path\":\"C:/Users/25750/Desktop/usmind/tools/nginx-1.30.5/conf/nginx.conf\",\"content\":\"# ============================================================\\n# USMIND · nginx 部署配置（新版架构）\\n#   - 站点1 motorlab（保留旧项目）：入口 http://127.0.0.1:8766\\n#   - 站点2 usmind 用户端：静态托管 + API代理，入口 http://127.0.0.1:8866\\n#   - 站点3 usmind 管理后台：静态托管 + API代理，入口 http://127.0.0.1:8867\\n# ============================================================\\n\\nworker_processes  1;\\n\\nevents {\\n    worker_connections  256;\\n}\\n\\nhttp {\\n    include       mime.types;\\n    default_type  application/octet-stream;\\n\\n    # 安全加固：隐藏版本号、统一安全响应头\\n    server_tokens off;\\n\\n    sendfile        on;\\n    keepalive_timeout  65;\\n    client_max_body_size 300m;\\n\\n    add_header X-Content-Type-Options \\\"nosniff\\\" always;\\n    add_header X-Frame-Options \\\"SAMEORIGIN\\\" always;\\n    add_header Referrer-Policy \\\"strict-origin-when-cross-origin\\\" always;\\n\\n    access_log  logs/usmind-access.log;\\n    error_log   logs/usmind-error.log;\\n\\n    gzip  on;\\n    gzip_types text/css application/javascript application/json;\\n\\n    # ---------- motorlab 旧项目（保留） ----------\\n    server {\\n        listen       8766;\\n        server_name  127.0.0.1;\\n\\n        location / {\\n            root   ../../motorlab/web;\\n            index  index.html;\\n            try_files $uri $uri/ =404;\\n        }\\n\\n        location /api/ {\\n            proxy_pass http://127.0.0.1:8765;\\n            proxy_http_version 1.1;\\n            proxy_set_header Host $host;\\n            proxy_set_header X-Real-IP $remote_addr;\\n            proxy_set_header X-Forwarded-For $remote_addr;\\n            proxy_read_timeout 300s;\\n        }\\n    }\\n\\n    # ---------- USMIND 用户端 ----------\\n    server {\\n        listen       8866;\\n        server_name  127.0.0.1;\\n\\n        access_log  logs/usmind-user-access.log;\\n        error_log   logs/usmind-user-error.log;\\n\\n        # API 代理到 Spring Boot 后端\\n        location /api/ {\\n            proxy_pass http://127.0.0.1:8899;\\n            proxy_http_version 1.1;\\n            proxy_set_header Host $host;\\n            proxy_set_header X-Real-IP $remote_addr;\\n            proxy_set_header X-Forwarded-For $remote_addr;\\n            proxy_read_timeout 300s;\\n        }\\n\\n        # WebS'),(31939,1,'admin','GET','/api/admin/logs/interface-list','keyword=',200,1,'info','127.0.0.1','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/154.0.0.0 Safari/537.36 Edg/154.0.0.0',3,'','backend',NULL,'2026-10-01 11:00:22','{accept=application/json, text/plain, */*, accept-languag