\\n    include       mime.types;\\n    default_type  application/octet-stream;\\n\\n    # 安全加固：隐藏版本号、统一安全响应头\\n    server_tokens off;\\n\\n    sendfile        on;\\n    keepalive_timeout  65;\\n    client_max_body_size 300m;\\n\\n    add_header X-Content-Type-Options \\\"nosniff\\\" always;\\n    add_header X-Frame-Options \\\"SAMEORIGIN\\\" always;\\n    add_header Referrer-Policy \\\"strict-origin-when-cross-origin\\\" always;\\n\\n    access_log  logs/usmind-access.log;\\n    error_log   logs/usmind-error.log;\\n\\n    gzip  on;\\n    gzip_types text/css application/javascript application/json;\\n\\n    # ---------- motorlab 旧项目（保留） ----------\\n    server {\\n        listen       8766;\\n        server_name  127.0.0.1;\\n\\n        location / {\\n            root   ../../motorlab/web;\\n            index  index.html;\\n            try_files $uri $uri/ =404;\\n        }\\n\\n        location /api/ {\\n            proxy_pass http://127.0.0.1:8765;\\n            proxy_http_version 1.1;\\n            proxy_set_header Host $host;\\n            proxy_set_header X-Real-IP $remote_addr;\\n            proxy_set_header X-Forwarded-For $remote_addr;\\n            proxy_read_timeout 300s;\\n        }\\n    }\\n\\n    # ---------- USMIND 用户端 ----------\\n    server {\\n        listen       8866;\\n        server_name  127.0.0.1;\\n\\n        access_log  logs/usmind-user-access.log;\\n        error_log   logs/usmind-user-error.log;\\n\\n        # API 代理到 Spring Boot 后端\\n        location /api/ {\\n            proxy_pass http://127.0.0.1:8899;\\n            proxy_http_version 1.1;\\n            proxy_set_header Host $host;\\n            proxy_set_header X-Real-IP $remote_addr;\\n            proxy_set_header X-Forwarded-For $remote_addr;\\n            proxy_read_timeout 300s;\\n        }\\n\\n        # WebS'),(31973,1,'admin','GET','/api/admin/logs/interface-list','keyword=',200,1,'info','127.0.0.1','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Geck