CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(64) NOT NULL COMMENT '登录账号',
  `password` varchar(128) NOT NULL COMMENT 'BCrypt加密密码',
  `nickname` varchar(64) DEFAULT '' COMMENT '昵称',
  `avatar` varchar(512) DEFAULT '' COMMENT '头像URL',
  `email` varchar(128) DEFAULT '' COMMENT '邮箱',
  `phone` varchar(32) DEFAULT '' COMMENT '手机号',
  `role` varchar(16) DEFAULT 'USER' COMMENT '角色: ADMIN/USER',
  `status` tinyint DEFAULT '1' COMMENT '状态: 1启用 0禁用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `member_level` int DEFAULT '0',
  `member_expire` datetime DEFAULT NULL,
  `source` varchar(16) DEFAULT 'local',
  `openid_wechat` varchar(128) DEFAULT '',
  `openid_qq` varchar(128) DEFAULT '',
  `last_login_at` datetime DEFAULT NULL,
  `member_source` varchar(16) DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  KEY `idx_username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

